package com.portfolio.expensetracker;

import com.portfolio.expensetracker.category.Category;
import com.portfolio.expensetracker.transaction.TransactionType;
import com.portfolio.expensetracker.user.User;
import org.springframework.test.util.ReflectionTestUtils;

/**
 * Tiny factory for entities used by the unit tests.
 *
 * <p>Entity ids are normally generated by the database. Unit tests have no database, so
 * {@link ReflectionTestUtils#setField} writes the private {@code id} field directly. That is
 * acceptable in tests, but production code should never do it.
 */
public final class TestData {

    private TestData() {
    }

    public static User user(long id) {
        User user = new User("User " + id, "user" + id + "@example.com", "hash");
        ReflectionTestUtils.setField(user, "id", id);
        return user;
    }

    public static Category category(long id, User owner, String name, TransactionType type) {
        Category category = new Category(owner, name, "#123456", type);
        ReflectionTestUtils.setField(category, "id", id);
        return category;
    }
}
